// Real WebAudio playback and renderer microphone gating; site/worker transport
// is synthetic. The WAV fixture must be generated by the actual TTS separately.
const {app,ipcMain}=require('electron');
const assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const fixture=path.resolve(process.env.UMAY_TTS_FIXTURE||'.superpowers/tts-cutoff/default-0.wav');
const wav=fs.readFileSync(fixture);assert.equal(wav.toString('ascii',8,12),'WAVE');
let data;for(let i=12;i+8<=wav.length;){const size=wav.readUInt32LE(i+4);if(wav.toString('ascii',i,i+4)==='data'){data=wav.subarray(i+8,i+8+size);break;}i+=8+size+(size%2);}
assert.ok(data);const rate=wav.readUInt32LE(24);assert.equal(wav.readUInt16LE(22),1);assert.equal(wav.readUInt16LE(34),16);
function chunk(pcm){const h=Buffer.from(wav.subarray(0,44));h.writeUInt32LE(pcm.length+36,4);h.writeUInt32LE(pcm.length,40);return Buffer.concat([h,pcm]).toString('base64');}
const chunks=[];for(let at=0;at<data.length;at+=Math.round(rate*.08)*2)chunks.push(chunk(data.subarray(at,at+Math.round(rate*.08)*2)));
const text='Şu anda size yardımcı oluyorum, sorularınızı yanıtlamakta ve size bilgiler veriyorum, bane şef.';
app.setPath('userData',fs.mkdtempSync(path.join(os.tmpdir(),'umay-playback-check-')));
require('../src/main.cjs');const deadline=setTimeout(()=>{console.error('FAIL playback deadline');app.exit(1);},90000);
app.on('browser-window-created',(_e,window)=>{
 window.webContents.setAudioMuted(true);window.webContents.setBackgroundThrottling(false);window.on('show',()=>window.hide());
 window.webContents.once('did-finish-load',async()=>{
  let active=null,cancels=0;
  for(const name of ['api','speech'])ipcMain.removeHandler(name);
  ipcMain.handle('api',(_event,route,body)=>route==='/site/auth/me'?{id:'fixture',email:'test@example.test'}:route==='/site/chat/models'?{models:[]}:route.endsWith('/messages')?{run:{id:'run'}}:route.includes('/runs/')?{run:{status:'COMPLETED'}}:{conversation:{id:'chat',version:1},messages:[{role:'assistant',content:text}],conversations:[]});
  ipcMain.handle('speech',async(_event,method,params)=>{
   if(method==='status')return {stt:{installed:false},tts:{installed:false}};
   if(method==='voices')return [];
   if(method==='cancel'){if(active){active.cancelled=true;cancels++;}return true;}
   if(method!=='speak')return true;
   assert.equal(params.text,text);const turn={cancelled:false};active=turn;
   for(const audio of chunks){if(turn.cancelled)break;window.webContents.send('event',{event:'audio',audio});await new Promise(r=>setTimeout(r,28));}
   if(active===turn)active=null;return {cancelled:turn.cancelled};
  });
  const js=code=>window.webContents.executeJavaScript(code);
  try{
   await js('refresh()');
   await js(`window.originalEchoMatch=playbackEcho.matches.bind(playbackEcho);window.originalStop=stop;window.automaticStops=0;stop=(...args)=>{if(args[0]===true&&args[1]===true)automaticStops++;return originalStop(...args)};document.getElementById('speak').checked=true;liveRecognizer={accept(){},reset:async()=>{}};void 0;`);
   for(const control of [true,false,false,'human',false]){
    cancels=0;
    await js(`playbackEcho.matches=${control===true?'()=>false':'originalEchoMatch'};listening=true;recording=false;voiced=0;automaticStops=0;conversation={id:'chat',version:1};window.completed=false;window.inputCursor=null;window.humanMode=${control==='human'};window.pump=setInterval(async()=>{
     if(!audioContext)return;const now=audioContext.currentTime;inputCursor??=now-.14;
     while(inputCursor+.02<=now-.12){const frame=new Float32Array(320);for(let i=0;i<320;i++){const t=inputCursor+i/16000;if(humanMode&&sources.length){frame[i]=.08*Math.sin(t*16000*.227+Math.sin(t*16000*.013)*4);continue;}for(const p of playbackEcho.parts){const index=Math.floor((t-p.start)*2000);if(index>=0&&index<p.samples.length){frame[i]=p.samples[index]*.65;break;}}}inputCursor+=.02;await onFrame(frame);}
    },20);send('ses testi',true).then(()=>completed=true)`);
    const result=await js(`new Promise((resolve,reject)=>{const deadline=Date.now()+20000;let quietSince=0;const poll=()=>{if(completed&&!sources.length){quietSince||=Date.now();if(Date.now()-quietSince>250)return resolve({automaticStops,listening,recording});}else quietSince=0;if(Date.now()>deadline)return reject(Error('Playback incomplete'));setTimeout(poll,25)};poll()})`);
    await js('clearInterval(pump)');
    if(control===true||control==='human'){assert.ok(result.automaticStops>0);assert.ok(cancels>0);}
    else{assert.equal(result.automaticStops,0);assert.equal(cancels,0);}
    console.log(control===true?'REPRODUCED previous echo cutoff':control==='human'?'PASS genuine interruption still cancels playback':'PASS full reply and following reply survive loud playback echo',JSON.stringify(result));
   }
   await js('listening=false;liveRecognizer=null;stop()');clearTimeout(deadline);app.quit();
  }catch(error){console.error(error);clearTimeout(deadline);app.exit(1);}
 });
});
